INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (47,"Bismillâh ir-rahmân ir-rahîm { Qul huwa Allâhu ahad * Allâh s-samad * Lam yalid wa lam yûlad * wa lam yakul-la-hû kufu-wan ahad }

Bismillâh ir-rahmân ir-rahîm { Qul aAAoothu birabbi alfalaq * Min sharri ma khalaq * Wamin sharri ghasiqin ithawaqab * Wamin sharri annaffathatifee alAAuqad * Wamin sharri hasidin itha hasad }

Bismillâh ir-rahmân ir-rahîm { Qul aAAoothu birabbi alnnas * Maliki annas * Ilahi annas * Min sharri alwaswasi alkhannas * Allathee yuwaswisu fee sudoori annas * Mina aljinnati wannas }","Chapter 112 - Surat Al-'Ikhlāş
Chapter 113 - Surat Al-Falaq
Chapter 114 - Surat An-Nās",2,2,3,"alm3wzat_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (48,"Bismillâh ir-rahmân ir-rahîm { Qul huwa Allâhu ahad * Allâh s-samad * Lam yalid wa lam yûlad * wa lam yakul-la-hû kufu-wan ahad }

Bismillâh ir-rahmân ir-rahîm { Qul aAAoothu birabbi alfalaq * Min sharri ma khalaq * Wamin sharri ghasiqin ithawaqab * Wamin sharri annaffathatifee alAAuqad * Wamin sharri hasidin itha hasad }

Bismillâh ir-rahmân ir-rahîm { Qul aAAoothu birabbi alnnas * Maliki annas * Ilahi annas * Min sharri alwaswasi alkhannas * Allathee yuwaswisu fee sudoori annas * Mina aljinnati wannas }","Chapter 112 - Surat Al-'Ikhlāş
Chapter 113 - Surat Al-Falaq
Chapter 114 - Surat An-Nās",2,2,3,"alm3wzat_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (49,"Wajjahtu wajhiya lillathee fataras-samawati wal-arda haneefan wama ana minal-mushrikeen, inna salatee wanusukee wamahyaya wamamatee lillahi rabbil-AAalameen, la shareeka lahu wabithalika omirtu wa-ana minal-muslimeen. Allahumma antal-maliku la ilaha illa ant. anta rabbee wa-ana AAabduk, thalamtu nafsee waAAtaraftu bithanbee faghfir lee thunoobee jameeAAan innahu la yaghfiruth-thunooba illa ant. wahdinee li-ahsanil-akhlaqi la yahdee li-ahsaniha illa ant, wasrif AAannee sayyi-aha la yasrifu AAannee sayyi-aha illa ant, labbayka wasaAAdayk,walkhayru kulluhu biyadayk, washsharru laysa ilayk, ana bika wa-ilayk, tabarakta wataAAalayt, astaghfiruka wa-atoobu ilayk.

‘I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allah). Indeed my prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allah, You are the Sovereign, none has the right to be worshipped except You. You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You. Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You. Here I am, in answer to Your call, happy to serve you. All good is within Your hands and evil does not stem from You. I exist by your will and will return to you. Blessed and High are You, I seek Your forgiveness and repent unto You’

Allah does not create pure evil which does not have any good or contain any benefit, wisdom or mercy at all, nor does He punish anyone without having commited a sin. Something can be good in terms of its creation when viewed in a particular perspective and at the same time be evil when viewed in another way. Allah created the devil and by him, He tests His servants, so there are those who hate the devil, fight him and his way and they stand at enmity towards him and his followers and there are others who are at allegiance with the devil and follow his steps. So evil exists in His creatures by His will and wisdom, not in His actions or act of creating. ","",2,2,1,"salah_before_3");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (49,"Allahumma lakal-hamd anta noorus-samawati wal-ardi waman feehin, walakal-hamd, anta qayyimus-samawati walardi waman feehin, walakal-hamd, anta rabbus-samawati walardi waman feehin, walakal-hamd, laka mulkus-samawati walardi waman feehin, walakal-hamd, anta malikus-samawati walard, walakal-hamd, antal-haq, wawaAAdukal-haq, waqawlukal-haq, waliqa-okal-haq, waljannatu haq wannaru haq, wannabiyyoona haq, wa Muhammadun -PBU- haq, wassaAAatu haq, allahumma laka aslamt, waAAalayka tawakkalt, wabika amant, wa-ilayka anabt, wabika khasamt, wa-ilayka hakamt, faghfir lee ma qaddamt, wama akhkhart, wama asrart, wama aAAlant , antal-muqaddim, wa-antal-mu-akhkhir, la ilaha illa ant, anta ilahee la ilaha illa ant.

‘O Allah, to You belongs all praise, You are the Light of the heavens and the Earth and all that is within them. To You belongs all praise, You are the Sustainer of the heavens and the Earth and all that is within them. To You belongs all praise. You are Lord of the heavens and the Earth and all that is within them. To You belongs all praise and the kingdom of the heavens and the Earth and all that is within them. To You belongs all praise, You are the King of the heavens and the Earth and to You belongs all praise. You are The Truth, Your promise is true, your Word is true, and the Day in which we will encounter You is true, the Garden of Paradise is true and the Fire is true, and the Prophets are true, Muhammad -PBU- is true and the Final Hour is true. O Allah, unto You I have submitted, and upon You I have relied, and in You I have believed, and to You I have turned in repentance, and over You I have disputed, and to You I have turned for judgment. So forgive me for what has come to pass of my sins and what will come to pass, and what I have hidden and what I have made public. You are Al-Muqaddim and Al-Mu-akhkhir. None has the right to be worshipped except You, You are my Deity, none has the right to be worshipped except You’

Meaning of Al-Muqaddim and Al-Mu-akhkhir : Allah puts forward and favours whom He wills rom amongst His creation just as He defers and holds back whom He wills in accordance to His wisdom. E.g. Favouring man over the rest of creation, favouring the Prophets over the rest of mankind, favouring Muhammad -PBU- over all the Prophets and Messengers … etc.","",2,6,1,"salah_before_7");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (50,"Allahumma antas-salam waminkas-salam, tabarakta ya thal-jalali wal-ikram.

‘O Allah, You are As-Salam and from You is all peace, blessed are You, O Possessor of majesty and honour’

AS-Salam : The One Who is free from all defects and deficiencies.","",2,1,1,"salah_after_2");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (51,"Bismillâh ir-rahmân ir-rahîm { Qul huwa Allâhu ahad * Allâh s-samad * Lam yalid wa lam yûlad * wa lam yakul-la-hû kufu-wan ahad }

Bismillâh ir-rahmân ir-rahîm { Qul aAAoothu birabbi alfalaq * Min sharri ma khalaq * Wamin sharri ghasiqin ithawaqab * Wamin sharri annaffathatifee alAAuqad * Wamin sharri hasidin itha hasad }

Bismillâh ir-rahmân ir-rahîm { Qul aAAoothu birabbi alnnas * Maliki annas * Ilahi annas * Min sharri alwaswasi alkhannas * Allathee yuwaswisu fee sudoori annas * Mina aljinnati wannas } ","Chapter 112 - Surat Al-'Ikhlāş
Chapter 113 - Surat Al-Falaq
Chapter 114 - Surat An-Nās",2,0,3,"al_nawm_1");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (56,"La hawla wala quwwata illa billah.

‘There is no might nor power except with Allah’","AAabdullah Ibn Qays related that the Prophet -PBU- said to him : ‘O AAabdullah Ibn Qays, shall I not inform you of a treasure from the treasures of paradise?’ He -PBU- then said : ‘Say : La hawla wala quwwata illa billah.
‘There is no might nor power except with Allah’",2,6,1,"esteghfar_7");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (59,"Allahumma innee aAAoothu bika an adilla aw odal, aw azilla aw ozall, aw athlima aw othlam, aw ajhala aw yujhala AAalay.

‘O Allah, I take refuge with You lest I should stray or be led astray, or slip or be tripped, or oppress or be oppressed, or behave foolishly or be treated foolishly’

Slip : i.e. to commit a sin unintentionally.","",2,1,1,"mnzel_khurooj_2");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (65,"Immediately following the declaration of faith called by the mu-aththin, one says:
Wa-ana ashhadu an la ilaha illal-lahu wahdahu la shareeka lah, wa-anna Muhammadan AAabduhu warasooluh, radeetu billahi rabban wabimuhammadin rasoolan wabil-islami deena.

‘And I too bear witness that none has the right to be worshipped except Allah, alone, without partner, and that Muhammad is His salve and Messenger. I am pleased with Allah as a Lord, and Muhammad as a Messenger and Islam as a religion’","",2,1,1,"sound_016_2_2_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (67,"Qunoot Al-Witr (1) : Allahummah-dinee feeman hadayt, waAAafinee feeman AAafayt, watawallanee feeman tawallayt, wabarik lee feema aAAtayt, waqinee sharra ma qadayt, fa-innaka taqdee wala yuqda AAalayk, innahu la yathillu man walayt, [wala yaAAizzu man AAadayt], tabarakta rabbana wataAAalayt.

‘O Allah, guide me along with those whom You have guided, pardon me along with those whom You have pardoned, be an ally to me along with those whom You are an ally to and bless for me that which You have bestowed. Protect me from the evil You have decreed for verily You decree and none can decree over You.For surety, he whom you show allegiance to is never abased and he whom You take as an enemy is never honoured and mighty. O our Lord, Blessed and Exalted are You’

Evil you have decreed : Allah does not create pure evil which does not have any good or contain any benefit, wisdom or mercy at all, nor does He punish anyone without having commited a sin. Something can be good in terms of its creation when viewed in a particular perspective and at the same time be evil when viewed in another way. Allah created the devil and by him, He tests His servants, so there are those who hate the devil, fight him and his way and they stand at enmity towards him and his followers and there are others who are at allegiance with the devil and follow his steps. So evil exists in His creatures by His will and wisdom, not in His actions or act of creating.","",2,0,1,"sound_033_2_1_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (71,"Ibn AAumar said: It would be counted that the Messenger of Allah (s.a.a.w.) would say one hundred times at any one sitting before getting up :
Rabbigh-fir lee watub AAalay, innaka antat-tawwabul-ghafoor.

‘O my Lord, forgive me and turn towards me (to accept my repentance). Verily You are The Oft-Returning. The Oft-Forgiving’","",2,0,1,"sound_085_2_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (79,"He should also recite the following verse :
{ Huwa al-awwalu, waal-akhiru, waalththahiru waalbatinu wahuwa bikulli shayin AAaleem }

‘He is The First and The Last, Aththahir and Al-Batin and He knows well all things’

Aththahir : Indicates the greatness of His attributes and the insignificance of every single creation in respect to His greatness and Highness, for He is above all of His creation as regards His essence and attributes.
Al-Batin : Indicates His awareness and knowledge of all secrets, of that which is in the hearts and the most intimate of things just as it indicates His closeness and nearness to all in a manner which befits His majesty.","Chapter 57 - verse 3 , Surat Al-Ĥadīd.",2,3,1,"sound_041_2_4_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (84,"La ilaha illal-lahul-wahidul-qahhar, rabbus-samawati waalard wama baynahuma, alAAazeezul-ghaffar.

‘None has the right to be worshipped except Allah, The One, AL-Qahhar.Lord of the heavens and the Earth and all between them, The Exalted in Might, The Oft-Forgiving’

AL-Qahhar : The One Who has subdued all of creation and Whom all of creation are subservient to. All movements occur by His will.","",2,0,1,"sound_030_2_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (87,"When closing the eyes of the deceased : Allahummagh-fir li-name the dead- warfaAA darajatahu fil-mahdiyyeen, wakhlufhu fee AAaqibihi fil-ghabireen, waghfir lana walahu ya rabbal-AAalameen wafsah lahu fee qabrih, wanawwir lahu feeh.

‘O Allah, forgive -here the name of the deceased is mentioned- and raise his rank among the rightly guided, and be a successor to whom he has left behind, and forgive us and him O Lord of the worlds.Make spacious his grave and illuminate it for him’

A successor : one who succeeds another due to the latter’s absence or death. This is the correct meaning of the word khaleefah; thus, it is incorrect to believe that Adam is the khaleefah (vicegerent, as is commonly translated) of Allah on earth because Allah is never absent, and will never die. This supplication proves the correct understanding of this term and shows that Allah succeeds us and guards whom we leave behind when we die or are absent.","",2,0,1,"agmadalmayt_part");

INSERT INTO PRAYERS ( CAT_ID,PRA_TEXT,PRA_PREFE,LAN_ID,PRA_ORDER,PRA_REPETITION, PRA_AUD) VALUES (90,"AAaishah related that the Prophet (during his illness in which he passed away) would dip his hands in water and then he would wipe his face and say :
La ilaha illal-lah, inna lilmawti lasakarat.

‘None has the right to be worshipped except Allah, death does indeed contain agony’","",2,1,1,"almreed_part2");
